class MutableCounter {
    private int value = 0;
    void increment() { value++; } // nieatomowe, brak synchronizacji
    int getValue() { return value; }
}
MutableCounter counter = new MutableCounter();
// 4 watki x 200_000 wywolan counter.increment() bez synchronizacji
// -> rzeczywisty wynik CZESTO != oczekiwany (patrz Lesson07/Lesson09)

record ImmutablePoint(int x, int y) {
    ImmutablePoint przesun(int dx, int dy) {
        return new ImmutablePoint(x + dx, y + dy); // nowy obiekt, oryginal bez zmian
    }
}
ImmutablePoint punkt = new ImmutablePoint(1, 2);
// wiele watkow moze CZYTAC ten sam obiekt bezpiecznie - nie da sie go zmienic
ImmutablePoint przesuniety = punkt.przesun(10, 10); // nowa instancja, punkt bez zmian

