class MutableCounter { int value=0; void increment() { value++; } }
MutableCounter c = new MutableCounter();
Thread t1 = new Thread(() -> { for (int j=0;j<50_000;j++) c.increment(); });
Thread t2 = new Thread(() -> { for (int j=0;j<50_000;j++) c.increment(); });
t1.start(); t2.start(); t1.join(10_000); t2.join(10_000);
System.out.println("oczekiwany=100000 rzeczywisty="+c.value);

int[] wyniki = new int[4];
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i; t[i] = new Thread(() -> { int sum=0; for (int k=1;k<=1000;k++) sum+=k; wyniki[idx]=sum; }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(Arrays.toString(wyniki)); // wszystkie 500500

record Point(int x, int y) { Point move(int dx, int dy) { return new Point(x+dx, y+dy); } }
Point p = new Point(1,2);
boolean[] ok = {true};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) if (p.x()+p.y() != 3) ok[0]=false; });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(ok[0]); // zawsze true

record Money(long cents) { Money add(Money other) { return new Money(cents + other.cents()); } }
Thread[] t = new Thread[3];
for (int i=0;i<3;i++) t[i] = new Thread(() -> {
    Money suma = new Money(0);
    for (int j=0;j<1000;j++) suma = suma.add(new Money(100));
    System.out.println(suma.cents()); // 100000
});
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);

String[] scenariusze = {"lokalna zmienna int w metodzie", "statyczne pole int bez synchronizacji", "record z polami final", "statyczna final lista List.of(...)", "instancyjne pole ArrayList modyfikowane przez wiele watkow"};
boolean[] wspoldzielony = {false, true, true, true, true};
boolean[] mutowalny = {true, true, false, false, true};
for (int i=0;i<5;i++) {
    boolean bezpieczny = !wspoldzielony[i] || !mutowalny[i];
    System.out.println(scenariusze[i] + ": " + (bezpieczny ? "THREAD-SAFE" : "NIEBEZPIECZNY"));
}

class UnsafeListWrapper { List<Integer> lista = new ArrayList<>(); void add(int v) { lista.add(v); } }
UnsafeListWrapper w = new UnsafeListWrapper();
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int base=i; t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) w.add(base*10_000+j); }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(10_000);
System.out.println("oczekiwane=40000 rzeczywiste="+w.lista.size());

record Config(String name, int maxRetries) { Config withName(String n) { return new Config(n, maxRetries); } }
Config cfg = new Config("prod", 3);
boolean[] ok = {true};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) if (cfg.name()==null || cfg.maxRetries()<0) ok[0]=false; });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(ok[0]); // zawsze true

MutableCounter c = new MutableCounter();
Thread[] t = new Thread[8];
for (int i=0;i<8;i++) t[i] = new Thread(() -> { for (int j=0;j<50_000;j++) c.increment(); });
for (Thread th : t) th.start();
for (Thread th : t) th.join(10_000);
int expected = 400_000;
System.out.println("oczekiwany="+expected+" rzeczywisty="+c.value+" roznica="+(expected-c.value));

static int square(int n) { return n * n; }
boolean[] ok = {true};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int base=i*1000; t[i] = new Thread(() -> { for (int n=base;n<base+1000;n++) if (square(n) != n*n) ok[0]=false; }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(ok[0]); // zawsze true

// (a) MutableCounter, 4x50_000 increment() -> czesto niepoprawny wynik
// (b) int[] czesciowe = new int[4]; kazdy watek: for(j<50_000) czesciowe[idx]++;
// po join(): suma = Arrays.stream(czesciowe).sum(); // zawsze poprawny (200000)
System.out.println("(a) czesto bledny, (b) zawsze poprawny");

record ImmutableSnapshot(List<String> items) {
    static ImmutableSnapshot of(List<String> source) { return new ImmutableSnapshot(List.copyOf(source)); }
}
List<String> oryginal = new ArrayList<>(List.of("a","b"));
ImmutableSnapshot snap = ImmutableSnapshot.of(oryginal);
oryginal.add("c");
System.out.println(snap.items()); // [a, b] - bez zmian

record ImmutablePath(List<Point> points) {
    ImmutablePath addPoint(Point p) { List<Point> nowa = new ArrayList<>(points); nowa.add(p); return new ImmutablePath(List.copyOf(nowa)); }
}
ImmutablePath sciezka = new ImmutablePath(List.of(new Point(0,0)));
// 3 watki czytajace sciezka.points() rownolegle - zawsze bezpieczne, bo lista jest niemutowalna

class FlagHolder { boolean flag = false; }
FlagHolder h = new FlagHolder();
Thread t1 = new Thread(() -> { for (int j=0;j<500;j++) h.flag = !h.flag; });
Thread t2 = new Thread(() -> { for (int j=0;j<500;j++) h.flag = !h.flag; });
t1.start(); t2.start(); t1.join(5_000); t2.join(5_000);
System.out.println("finalna flaga: " + h.flag + " (stan+wspoldzielony+mutowalny = ryzykowne)");

List<List<Integer>> czesciowe = new ArrayList<>();
for (int i=0;i<4;i++) czesciowe.add(new ArrayList<>());
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i; t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) czesciowe.get(idx).add(j); }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(10_000);
List<Integer> finalna = new ArrayList<>();
for (List<Integer> lista : czesciowe) finalna.addAll(lista);
System.out.println(finalna.size()); // zawsze 40000

record ScoreBoard(Map<String,Integer> scores) {
    ScoreBoard { scores = Map.copyOf(scores); } // konstruktor kompaktowy
}
ScoreBoard sb = new ScoreBoard(Map.of("Ala", 10, "Bob", 20));
boolean[] ok = {true};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) if (!sb.scores().get("Ala").equals(10)) ok[0]=false; });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(ok[0]);

StringBuilder wspolny = new StringBuilder();
// (a) 4 watki x 5_000 append("x") na wspolny - czesto dlugosc != 20000
StringBuilder[] lokalne = new StringBuilder[4];
// (b) kazdy watek buduje wlasny StringBuilder, main laczy je po join() - zawsze poprawne 20000

record Temperature(double celsius) {
    double toFahrenheit() { return celsius * 9/5 + 32; }
    static Temperature fromFahrenheit(double f) { return new Temperature((f-32) * 5/9); }
}
Temperature t20 = new Temperature(20);
boolean[] ok = {true};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) { double f = t20.toFahrenheit(); Temperature z = Temperature.fromFahrenheit(f); if (Math.abs(z.celsius()-20) > 0.001) ok[0]=false; } });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(ok[0]);

record AlmostImmutable(int[] data) {}
int[] tablica = {1,2,3};
AlmostImmutable ai = new AlmostImmutable(tablica);
tablica[0] = 999;
System.out.println(Arrays.toString(ai.data())); // [999, 2, 3] - ZLAMANA niemutowalnosc!

record TrulyImmutable(int[] data) {
    TrulyImmutable { data = Arrays.copyOf(data, data.length); } // defensywna kopia
}
int[] tablica = {1,2,3};
TrulyImmutable ti = new TrulyImmutable(tablica);
tablica[0] = 999;
System.out.println(Arrays.toString(ti.data())); // [1, 2, 3] - niezmienione!

class UnsafeBankAccount { int balance=0; void deposit(int a) { balance += a; } }
record BankAccountSnapshot(int balance) { BankAccountSnapshot deposit(int a) { return new BankAccountSnapshot(balance+a); } }
// (a) wspolny UnsafeBankAccount, 4x20_000 deposit(1) -> czesto != 80000
// (b) kazdy watek: lokalny BankAccountSnapshot, 20_000x deposit(1), wyniki sumowane po join() -> zawsze 80000

List<String> withEvent(List<String> events, String event) { List<String> nowa = new ArrayList<>(events); nowa.add(event); return List.copyOf(nowa); }
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i; t[i] = new Thread(() -> {
    List<String> lokalna = List.of();
    for (int j=0;j<1000;j++) lokalna = withEvent(lokalna, "event"+idx+"-"+j);
    System.out.println(lokalna.size()); // 1000
}); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);

record Price(java.math.BigDecimal value, java.time.Instant timestamp) {}
static Price current = new Price(java.math.BigDecimal.ZERO, java.time.Instant.now()); // BEZ volatile
// watek pisarz: 5x (Thread.sleep(50); current = new Price(...))
// watki czytelnicy: co 10ms odczytuja current (zawsze SPOJNY obiekt, ale bez gwarancji SZYBKIEJ widocznosci bez volatile)

record ImmutableCounter(int value) { ImmutableCounter increment() { return new ImmutableCounter(value+1); } }
ImmutableCounter c = new ImmutableCounter(0);
for (int i=0;i<100_000;i++) c = c.increment();
System.out.println(c.value()); // 100000
System.out.println("Sekwencyjny lancuch - kazdy krok zalezy od poprzedniego, nie da sie trywialnie zrownoleglic");

List<List<Integer>> czesciowe = new ArrayList<>();
for (int i=0;i<4;i++) czesciowe.add(new ArrayList<>());
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i, poczatek=i*250; t[i] = new Thread(() -> { for (int k=poczatek;k<poczatek+250;k++) czesciowe.get(idx).add(k*k); }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
long suma = czesciowe.stream().flatMap(List::stream).mapToLong(Integer::longValue).sum();
long sekwencyjna = java.util.stream.IntStream.range(0,1000).mapToLong(k -> (long)k*k).sum();
System.out.println(suma == sekwencyjna);

static final List<Integer> sharedList = new ArrayList<>();
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int base=i; t[i] = new Thread(() -> { for (int j=0;j<10_000;j++) sharedList.add(base*10_000+j); }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(10_000);
System.out.println("oczekiwane=40000 rzeczywiste="+sharedList.size()+" (final chroni TYLKO referencje, nie zawartosc!)");

// (a) 4 watki modyfikujace WSPOLNE pole -> czesto niepoprawny wynik
// (b) 4 watki, kazdy WLASNE pole, sumowane po join() -> zawsze poprawny
// (c) tylko 1 watek pisze (200_000 razy), pozostale 3 tylko czytaja na koncu -> zawsze poprawny (brak rywalizacji o zapis)

record Cache(Map<String,String> data) {
    Cache withEntry(String k, String v) { Map<String,String> nowa = new HashMap<>(data); nowa.put(k,v); return new Cache(Map.copyOf(nowa)); }
}
Cache oryginal = new Cache(Map.of("a","1"));
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx=i; t[i] = new Thread(() -> { Cache pochodny = oryginal.withEntry("nowy"+idx, "wartosc"); System.out.println(pochodny.data().size()); }); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(oryginal.data().size()); // zawsze 1, oryginal niezmieniony

// (A) eliminacja wspoldzielenia: int[] czesciowe = new int[4]; kazdy watek: for(j<50_000) czesciowe[idx]++; suma po join()
// (B) eliminacja mutowalnosci: ImmutableCounter c = new ImmutableCounter(0); for (int i=0;i<200_000;i++) c = c.increment(); (sekwencyjnie w 1 watku)
System.out.println("(A) rownolegle, mniej alokacji, wieksza przepustowosc");
System.out.println("(B) sekwencyjne, 200000 alokacji nowych obiektow, prostsze rozumowanie o poprawnosci");
